import{economyWarnings,emptyEconomy,isCurrentEconomy,type EconomyState}from'../core/economy';import{MODULE_ID}from'../types';import{combatPass,ECONOMY_FLAG}from'./economy';
const esc=(value:unknown)=>String(value??'').replace(/[&<>"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[character]!));
function economyBadge(state:EconomyState|undefined,round:number,pass:number){const current=isCurrentEconomy(state,round,pass)?state!:emptyEconomy(round,pass);const warnings=economyWarnings(current),over=warnings.length>0,t=(key:string)=>game.i18n.localize(key),parts=[`${t('SDF.Economy.Short.Free')}${current.free}`,`${t('SDF.Economy.Short.Simple')}${current.simpleUsed}/2`,`${t('SDF.Economy.Short.Complex')}${current.complexUsed}/1`];if(current.interrupts.length)parts.push(`${t('SDF.Economy.Short.Interrupt')}${current.interrupts.length}`);const title=esc(over?warnings.map(t).join(' · '):t('SDF.Economy.Title'));return`<div class="sdf-economy${over?' over':''}" title="${title}">${over?'<i class="fas fa-triangle-exclamation"></i> ':''}${parts.map(esc).join(' · ')}</div>`}
export function renderEconomyTracker(_app:any,html:any){try{const root:HTMLElement|null=html instanceof HTMLElement?html:html?.[0]??null;const combat=game.combat;if(!root||!combat)return;const round=Number(combat.round)||0,pass=combatPass(combat);root.querySelectorAll<HTMLElement>('[data-combatant-id]').forEach(row=>{if(row.querySelector('.sdf-economy'))return;const combatant=combat.combatants?.get(row.dataset.combatantId!);if(!combatant)return;const state=combatant.getFlag(MODULE_ID,ECONOMY_FLAG)as EconomyState|undefined;const target=row.querySelector('.token-name')??row;target.insertAdjacentHTML('beforeend',economyBadge(state,round,pass))})}catch(error){console.warn(`${MODULE_ID} | economy tracker render failed`,error)}}
