import{extractors}from'../core/flows/registry';import type{FlowOrigin}from'../core/flows/spec';import{cardSections}from'./card-sections';
export function extendedProgressExtractor(origin:FlowOrigin){const data=origin.data??{},hits=Number(data.values?.extendedHits?.value??data.values?.hits?.value),threshold=Number(data.threshold?.value);return{extended:{hits:Number.isFinite(hits)?hits:undefined,threshold:Number.isFinite(threshold)?threshold:undefined,complete:Number.isFinite(hits)&&Number.isFinite(threshold)&&hits>=threshold}}}
export function registerGeneralPresentation(){if(!extractors.has('extendedProgress'))extractors.register('extendedProgress',extendedProgressExtractor);if(!cardSections.has('extendedProgress'))cardSections.register('extendedProgress',({transaction,escape,localize})=>{const extended=(Object.values(transaction.branches)[0]?.stageData.origin as any)?.extended;if(!extended||extended.hits===undefined)return'';const threshold=extended.threshold,complete=extended.complete,progress=threshold?Math.min(100,Math.round((extended.hits/Math.max(1,threshold))*100)):0;return`<div class="sdf-combat-origin sdf-extended-origin"><div class="sdf-combat-group"><strong><i class="fas fa-hourglass-half"></i> ${escape(localize('SDF.Extended.Label'))}</strong><div class="metric-row"><span class="value">${escape(localize('SDF.Extended.Progress'))}:</span><span class="value-result">${escape(extended.hits)}${threshold!==undefined?` / ${escape(threshold)}`:''}</span></div>${threshold!==undefined?`<div class="sdf-extended-bar"><span style="width:${progress}%"></span></div>`:''}${complete?`<div class="sdf-verdict sdf-verdict--success"><i class="fas fa-check"></i> ${escape(localize('SDF.Extended.Complete'))}</div>`:''}</div></div>`})}
