import {DiceFlowAPI} from './api'; import {chummerModifiers} from './core/chummer'; import {advance} from './core/flows/engine'; import {extractors,flows} from './core/flows/registry'; import {actorModifiers,ModifierRegistry} from './core/modifiers'; import {reducers} from './core/reducers'; import {addTarget,setCalledShotAnnounced,setConfirmation,setDamageApplied,setDefense,setPendingEffects,setResistance,type PendingEffectEntry} from './core/transaction';import{isGlobalConfirmation}from'./core/flows/confirmation'; import {MODULE_ID} from './types'; import {installWrappers,registerCaptureSafetyNet,registerFallbackHook,shouldSuppressFollowupMessage} from './foundry/integration'; import {getTransaction,saveTransaction} from './foundry/store'; import {socket} from './foundry/socket';
import{handleCardAction}from'./foundry/actions';
import{registerCombatPresentation}from'./foundry/combat';
import{registerMagicPresentation}from'./foundry/magic';
import{registerMatrixPresentation}from'./foundry/matrix';
import{registerGeneralPresentation}from'./foundry/general';
import{registerItemPresentation,registerItemUseHook}from'./foundry/itemuse';
import{registerCoreFlowSpecs}from'./core/flows/specs';
import{installCalledShotInjection}from'./foundry/calledshot';
import{applyEconomyMutation,resetStaleEconomy,type EconomyPayload}from'./foundry/economy';
import{renderEconomyTracker}from'./foundry/tracker-ui';
registerCoreFlowSpecs();registerCombatPresentation();registerMagicPresentation();registerMatrixPresentation();registerGeneralPresentation();registerItemPresentation();const modifiers=new ModifierRegistry();const api=new DiceFlowAPI(modifiers);
Hooks.once('init',()=>{modifiers.register('active-effects',actorModifiers,100);modifiers.register('chummer-core',chummerModifiers,50);flows.checkCapabilities(game.shadowrun5e?.tests??{},id=>reducers.has(id),id=>extractors.has(id));const mod=game.modules.get(MODULE_ID);if(mod)mod.api=api;game.settings.register(MODULE_ID,'modifierPresets',{name:'SDF.Settings.Presets',scope:'user',config:false,type:Object,default:{}});game.settings.register(MODULE_ID,'deferAmmo',{name:'SDF.Settings.DeferAmmo.Name',hint:'SDF.Settings.DeferAmmo.Hint',scope:'world',config:true,type:Boolean,default:true,requiresReload:true});game.settings.register(MODULE_ID,'deferEffects',{name:'SDF.Settings.DeferEffects.Name',hint:'SDF.Settings.DeferEffects.Hint',scope:'world',config:true,type:Boolean,default:true,requiresReload:true});console.info(`${MODULE_ID} | initialized`)});
Hooks.on('preCreateChatMessage',(document:any,data:any)=>shouldSuppressFollowupMessage(document?.toObject?.()??data)?false:undefined);
Hooks.once('ready',()=>{socket.register('addTarget',async(req,message)=>{const tx=(await getTransaction(message))!;await saveTransaction(message,addTarget(tx,req.expectedRevision,req.userId,req.payload as any))});socket.register('defend',async(req,message)=>{const tx=(await getTransaction(message))!;const p=req.payload as any;await saveTransaction(message,setDefense(tx,req.expectedRevision,req.userId,p.targetId,p.roll,p.flow))});socket.register('resist',async(req,message)=>{const tx=(await getTransaction(message))!;const p=req.payload as any;await saveTransaction(message,setResistance(tx,req.expectedRevision,req.userId,p.targetId,p.roll,p.finalDamage))});socket.register('advance',async(req,message)=>{const tx=(await getTransaction(message))!,p=req.payload as any,spec=flows.get(tx.flowId),stage=spec.stages.find(value=>value.id===p.stageId),branch=tx.branches[p.branchId];if(!stage||!branch)throw new Error('Invalid flow stage');const reduced=reducers.get(stage.reduce)({transactionId:tx.id,branch,origin:tx.origin,roll:p.roll,stage,data:p.data});await saveTransaction(message,advance(tx,p.branchId,p.stageId,p.roll,reduced,flows))});socket.register('confirm',async(req,message)=>{const tx=(await getTransaction(message))!,p=req.payload as any,spec=flows.get(tx.flowId),declared=spec.stages.flatMap(value=>value.confirm??[]).some(value=>value.id===p.confirmationId&&value.kind===p.kind)||isGlobalConfirmation(p.confirmationId,p.kind);if(!declared)throw new Error('Invalid confirmation');await saveTransaction(message,setConfirmation(tx,req.expectedRevision,req.userId,p.branchId,p.confirmationId,p.value))});socket.register('pendingEffects',async(req,message)=>{const tx=(await getTransaction(message))!,p=req.payload as any,entries=(p.entries??[])as PendingEffectEntry[],user=game.users.get(req.userId);if(user&&!user.isGM&&user.id!==tx.authorId&&entries.some(entry=>tx.branches[entry.branchId]?.actorUuid!==p.actorUuid))throw new Error('Branch ownership required');await saveTransaction(message,setPendingEffects(tx,tx.revision,req.userId,entries))});socket.register('damageApplied',async(req,message)=>{const tx=(await getTransaction(message))!;const p=req.payload as any;await saveTransaction(message,setDamageApplied(tx,req.expectedRevision,req.userId,p.targetId,{value:p.value,type:p.type}))});socket.register('calledShot',async(req,message)=>{const tx=(await getTransaction(message))!;const p=req.payload as any;await saveTransaction(message,setCalledShotAnnounced(tx,req.expectedRevision,req.userId,Boolean(p.value)))});socket.register('economy',async(req)=>{await applyEconomyMutation(req.payload as unknown as EconomyPayload)});socket.start();installWrappers();installCalledShotInjection();registerFallbackHook();registerCaptureSafetyNet();registerItemUseHook()});
Hooks.on('renderCombatTracker',(app:any,html:any)=>renderEconomyTracker(app,html));
Hooks.on('updateCombat',(combat:any)=>{if(game.user.isGM)resetStaleEconomy(combat)});
Hooks.on('renderChatMessageHTML',(message:any,html:HTMLElement)=>{const root=html.querySelector('.sr5-dice-flow');if(!root)return;root.querySelectorAll<HTMLElement>('[data-sdf-action]').forEach(el=>el.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();void handleCardAction(api,message,el)}))});
export{api};
