import{advance}from'./engine';import{FlowRegistry}from'./registry';import{resolvedTestClasses,type StageSpec}from'./spec';import{ReducerRegistry}from'../reducers';import{mutate}from'../transaction';import type{Branch,RollRecord,Transaction}from'../../types';
export interface FollowupInput {testClass:string;actorUuid?:string;targetId?:string;data?:unknown}
export type RouteResult={status:'captured';transaction:Transaction;branch:Branch;stage:StageSpec}|{status:'duplicate';transaction:Transaction}|{status:'unmatched';transaction:Transaction;reason:string};
type CandidateResult={branch:Branch;stage:StageSpec}|{reason:string};
const rollExists=(tx:Transaction,id:string)=>Object.values(tx.branches).some(branch=>Object.values(branch?.rolls??{}).some(roll=>roll.id===id))||tx.events.some(value=>value.type==='followup.unmatched'&&value.payload.rollId===id);
function candidates(tx:Transaction,input:FollowupInput,registry:FlowRegistry,allowUniqueSelf=false):CandidateResult{let spec;try{spec=registry.get(tx.flowId)}catch{return{reason:'flow-unavailable'}}const branch=input.targetId?tx.branches[input.targetId]:undefined;if(input.targetId&&!branch)return{reason:'target-missing'};const branches=branch?[branch]:Object.values(tx.branches);for(const candidate of branches){const stage=spec.stages.find(value=>value.id===candidate.stageId&&resolvedTestClasses(value,tx.origin).includes(input.testClass));if(!stage)continue;const kindMatches=stage.branch==='self'?candidate.kind==='self':candidate.kind==='target';const actorMatches=input.targetId!==undefined||candidate.actorUuid===input.actorUuid||allowUniqueSelf&&!input.actorUuid&&candidate.kind==='self'&&branches.filter(value=>value.kind==='self'&&value.stageId===stage.id).length===1;if(kindMatches&&actorMatches)return{branch:candidate,stage}}return{reason:'stage-unmatched'}}
export function canRouteFollowup(tx:Transaction,input:FollowupInput,registry:FlowRegistry){return'branch'in candidates(tx,input,registry,true)}
export function routeFollowup(tx:Transaction,input:FollowupInput,roll:RollRecord,userId:string,registry:FlowRegistry,reducers:ReducerRegistry):RouteResult{if(rollExists(tx,roll.id))return{status:'duplicate',transaction:tx};const match=candidates(tx,input,registry);if(!('branch'in match)){const updated=mutate(tx,tx.revision,userId,()=>{},'followup.unmatched',{rollId:roll.id,testClass:input.testClass,reason:match.reason});return{status:'unmatched',transaction:updated,reason:match.reason}}const reduced=reducers.get(match.stage.reduce)({transactionId:tx.id,branch:match.branch,origin:tx.origin,roll,stage:match.stage,data:input.data});const updated=advance(tx,match.branch.id,match.stage.id,roll,reduced,registry,userId);return{status:'captured',transaction:updated,branch:updated.branches[match.branch.id]!,stage:match.stage}}
