import{event}from'../transaction';import type{RollRecord,Transaction}from'../../types';import{flows,type FlowRegistry}from'./registry';import type{ReducedStage,StageSpec}from'./spec';
const clone=<T>(value:T):T=>structuredClone(value);
function nextStage(stage:StageSpec,reduced:ReducedStage){if(stage.next.always)return stage.next.always;if(reduced.outcome==='success'&&stage.next.onSuccess)return stage.next.onSuccess;if(reduced.outcome==='failure'&&stage.next.onFailure)return stage.next.onFailure;throw new Error(`No transition from stage ${stage.id} for outcome ${reduced.outcome??'none'}`)}
export function advance(tx:Transaction,branchId:string,stageId:string,roll:RollRecord,reduced:ReducedStage,registry:FlowRegistry=flows,userId=tx.authorId):Transaction{const spec=registry.get(tx.flowId);const stage=spec.stages.find(candidate=>candidate.id===stageId);if(!stage)throw new Error(`Unknown stage ${stageId} in flow ${spec.id}`);const current=tx.branches[branchId];if(!current)throw new Error(`Unknown branch: ${branchId}`);if(current.stageId!==stageId)throw new Error(`Branch ${branchId} is at stage ${current.stageId}, not ${stageId}`);if(current.rolls[stageId])throw new Error(`Stage already resolved: ${stageId}`);if(stage.branch==='self'&&current.kind!=='self'||stage.branch==='perTarget'&&current.kind!=='target')throw new Error(`Stage ${stageId} does not accept branch kind ${current.kind}`);const out=clone(tx),branch=out.branches[branchId]!;branch.rolls[stageId]=clone(roll);if(reduced.stageData!==undefined)branch.stageData[stageId]=clone(reduced.stageData);Object.assign(branch.derived,reduced.derived??{});branch.stageId=nextStage(stage,reduced);out.complete=Object.values(out.branches).length>0&&Object.values(out.branches).every(candidate=>candidate.stageId==='done');out.revision++;out.updatedAt=Date.now();out.events.push(event('stage.advanced',userId,{branchId,stageId,rollId:roll.id,nextStageId:branch.stageId}));return out}
