import type{FlowOrigin,FlowSpec,OriginExtractor}from'./spec';
export interface FlowCapability {spec:FlowSpec;enabled:boolean;missingTestClasses:string[];missingReducers:string[];missingExtractors:string[]}
export class ExtractorRegistry{private extractors=new Map<string,OriginExtractor>();register(id:string,extractor:OriginExtractor){if(this.extractors.has(id))throw new Error(`Extractor already registered: ${id}`);this.extractors.set(id,extractor);return()=>this.extractors.delete(id)}get(id:string){const extractor=this.extractors.get(id);if(!extractor)throw new Error(`Unknown extractor: ${id}`);return extractor}has(id:string){return this.extractors.has(id)}ids(){return[...this.extractors.keys()]}}
export class FlowRegistry{private specs:FlowSpec[]=[];private capabilities=new Map<string,FlowCapability>();register(spec:FlowSpec){if(this.specs.some(existing=>existing.id===spec.id))throw new Error(`FlowSpec already registered: ${spec.id}`);this.specs.push(spec);this.capabilities.delete(spec.id);return()=>{this.specs=this.specs.filter(existing=>existing.id!==spec.id);this.capabilities.delete(spec.id)}}get(id:string){const spec=this.specs.find(candidate=>candidate.id===id);if(!spec)throw new Error(`Unknown FlowSpec: ${id}`);const capability=this.capabilities.get(id);if(capability&&!capability.enabled)throw new Error(`FlowSpec disabled: ${id}`);return spec}match(origin:FlowOrigin){return this.specs.find(spec=>(this.capabilities.get(spec.id)?.enabled??true)&&spec.match(origin))}all(){return[...this.specs]}checkCapabilities(tests:Record<string,unknown>,hasReducer:(id:string)=>boolean=()=>true,hasExtractor:(id:string)=>boolean=()=>true,warn:(message:string)=>void=console.warn){const result:FlowCapability[]=[];for(const spec of this.specs){const missingTestClasses=[...new Set(spec.stages.flatMap(stage=>stage.testClasses))].filter(name=>!name.startsWith('$')&&!tests[name]);const missingReducers=[...new Set(spec.stages.map(stage=>stage.reduce))].filter(name=>!hasReducer(name));const missingExtractors=[...new Set(spec.originExtract??[])].filter(name=>!hasExtractor(name));const capability={spec,enabled:missingTestClasses.length===0&&missingReducers.length===0&&missingExtractors.length===0,missingTestClasses,missingReducers,missingExtractors};this.capabilities.set(spec.id,capability);result.push(capability);if(!capability.enabled)warn(`sr5-dice-flow | Disabled FlowSpec ${spec.id}; missing tests: ${missingTestClasses.join(', ')||'none'}; missing reducers: ${missingReducers.join(', ')||'none'}; missing extractors: ${missingExtractors.join(', ')||'none'}`)}return result}}
export const flows=new FlowRegistry();export const extractors=new ExtractorRegistry();
