import type {Modifier,ModifierContext,ModifierProvider} from '../types';
export class ModifierRegistry {#providers=new Map<string,{priority:number,provider:ModifierProvider}>();register(id:string,provider:ModifierProvider,priority=0){if(this.#providers.has(id))throw new Error(`Provider already registered: ${id}`);this.#providers.set(id,{priority,provider});return()=>this.#providers.delete(id)}async resolve(context:ModifierContext,existing:Modifier[]=[]){const candidates=[...existing];for(const [,entry]of[...this.#providers].sort((a,b)=>b[1].priority-a[1].priority))candidates.push(...await entry.provider(context));const seen=new Set<string>();return candidates.sort((a,b)=>(b.priority??0)-(a.priority??0)).filter(m=>{const key=m.fingerprint??m.id;if(seen.has(key))return false;seen.add(key);return true})}}
export function actorModifiers(context:ModifierContext):Modifier[]{const changes=context.actor?.effects?.flatMap((e:any)=>e.active===false?[]:(e.changes??[]))??[];return changes.filter((c:any)=>String(c.key).includes('test')||String(c.key).includes('pool')).map((c:any,i:number)=>({id:`ae-${i}-${c.key}`,label:c.label??c.key,value:Number(c.value)||0,source:'Active Effect',fingerprint:c.flags?.['sr5-dice-flow']?.fingerprint??`${c.key}:${c.value}`,priority:100}))}
