import type{StageReducer}from'../spec';import type{FlowSpec}from'../spec';import type{Branch,RollRecord}from'../../../types';
const spellOf=(branch:Branch)=>(branch.stageData.origin as any)?.spell;
export const spellDefenseReducer:StageReducer=({origin,branch,roll,data})=>{const raw=(data??{})as any,spell=spellOf(branch),indirect=spell?.category==='combat'&&spell?.combatType==='indirect',damage=raw.modifiedDamage??raw.incomingDamage,netHits=Math.max(0,(origin.hits??0)-(roll.hits??0)),baseDamage=raw.incomingDamage?.value??damage?.base??origin.baseDamage,modifiedDamage=damage?.value??baseDamage,damageType=damage?.type?.value??origin.damageType,needsSoak=indirect&&netHits>0&&Number(modifiedDamage??0)>0;return{outcome:needsSoak?'success':'failure',stageData:raw,derived:{netHits,baseDamage,modifiedDamage,damageType,finalDamage:needsSoak?undefined:netHits===0?0:Math.max(0,Number(modifiedDamage??baseDamage??0))}}};
export const drainResistReducer:StageReducer=({roll,data})=>{const raw=(data??{})as any,drain=raw.modifiedDrain??raw.incomingDrain,value=Math.max(0,Number(drain?.value??drain?.base??0)),type=drain?.type?.value;return{outcome:value>0?'success':'failure',stageData:raw,derived:{drainHits:roll.hits??0,drainDamage:value,drainType:type}}};
const spellTargetInitial=(origin?:RollRecord)=>origin?.defenseTest&&(origin.hits??0)>0?'defense':'done';
const spellStages:FlowSpec['stages']=[{id:'defense',branch:'perTarget',testClasses:['$origin.defenseTest'],trigger:'button',reduce:'spellDefense',next:{onSuccess:'soak',onFailure:'done'}},{id:'soak',branch:'perTarget',testClasses:['$origin.resistanceTest','PhysicalResistTest'],trigger:'button',reduce:'combatSoak',next:{always:'done'},confirm:[{id:'damageApplied',kind:'damage',when:'derived.finalDamage'}]},{id:'drain',branch:'self',testClasses:['DrainTest'],trigger:'systemFollowup',reduce:'drainResist',next:{always:'done'},confirm:[{id:'drainApplied',kind:'drain',when:'derived.drainDamage'}]}];
export const spellcasting:FlowSpec={id:'spellcasting',match:origin=>origin.testClass==='SpellCastingTest',branches:'targets+self',initialStage:(branch,origin)=>branch.kind==='self'?'drain':spellTargetInitial(origin),originExtract:['spellOrigin'],cardSections:['spellOrigin'],stages:spellStages};
export const summonServicesReducer:StageReducer=({origin,roll})=>{const spiritHits=roll.hits??0,services=Math.max(0,(origin.hits??0)-spiritHits);return{outcome:services>0?'success':'failure',derived:{spiritHits,services}}};
const conjureDrainStage:FlowSpec['stages'][number]={id:'drain',branch:'self',testClasses:['DrainTest'],trigger:'button',action:'conjure-drain',reduce:'drainResist',next:{always:'done'},confirm:[{id:'drainApplied',kind:'drain',when:'derived.drainDamage'}]};
export const summoning:FlowSpec={id:'summoning',match:origin=>origin.testClass==='SummonSpiritTest',branches:'single',initialStage:()=> 'summon-opposed',stages:[{id:'summon-opposed',branch:'self',testClasses:['OpposedSummonSpiritTest'],trigger:'button',action:'conjure-opposed',gm:true,reduce:'summonServices',next:{always:'drain'}},conjureDrainStage]};
export const ritual:FlowSpec={id:'ritual',match:origin=>origin.testClass==='RitualSpellcastingTest',branches:'single',initialStage:()=> 'ritual-opposed',stages:[{id:'ritual-opposed',branch:'self',testClasses:['OpposedRitualTest'],trigger:'button',action:'conjure-opposed',gm:true,reduce:'opposedHits',next:{always:'drain'}},conjureDrainStage]};
