const fadeStage:FlowSpec['stages'][number]={id:'fade',branch:'self',testClasses:['FadeTest'],trigger:'systemFollowup',reduce:'fadeResist',next:{always:'done'},confirm:[{id:'fadeApplied',kind:'fade',when:'derived.fadeDamage'}]};
