import {addTarget,createTransaction,migrate} from './core/transaction'; import {ModifierRegistry} from './core/modifiers'; import {MODULE_ID,type RollRecord,type Transaction} from './types'; import {createMessage,getTransaction,saveTransaction} from './foundry/store';
export class DiceFlowAPI{constructor(public modifiers:ModifierRegistry){}async create(origin:Omit<RollRecord,'id'|'createdAt'>,options:{authorId?:string;rollMode?:string}={}){let tx=createTransaction(origin,options.authorId??game.user.id);const message=await createMessage(tx,options.rollMode);tx=(await getTransaction(message))!;Hooks.callAll(`${MODULE_ID}.transactionCreated`,tx,message);return{transaction:tx,message}}get=getTransaction;registerModifierProvider(id:string,provider:any,priority=0){return this.modifiers.register(id,provider,priority)}async addTarget(message:any,input:any,expectedRevision?:number){const tx=await getTransaction(message);if(!tx)throw new Error('Transaction not found');const out=addTarget(tx,expectedRevision??tx.revision,game.user.id,input);await saveTransaction(message,out);Hooks.callAll(`${MODULE_ID}.targetStatusChanged`,out,input);return out}async recalculate(message:any,calculator:(tx:Transaction)=>Transaction){if(!game.user.isGM)throw new Error('GM only');const tx=await getTransaction(message);if(!tx)throw new Error('Transaction not found');const out=calculator(structuredClone(tx));if(out.id!==tx.id||out.revision<=tx.revision)throw new Error('Invalid recalculation');await saveTransaction(message,out);return out}migrate=migrate}
