import type{StageReducer,StageSpec}from'../spec';import type{FlowSpec}from'../spec';import type{Branch,RollRecord}from'../../../types';
export const COMBAT_ATTACK_TESTS=['MeleeAttackTest','RangedAttackTest','ThrownAttackTest'];
export const combatDefenseReducer:StageReducer=({origin,roll,data})=>{const raw=(data??{})as any,damage=raw.modifiedDamage??raw.incomingDamage,netHits=Math.max(0,(origin.hits??0)-(roll.hits??0)),baseDamage=raw.incomingDamage?.value??damage?.base??origin.baseDamage,modifiedDamage=damage?.value??baseDamage,damageType=damage?.type?.value??origin.damageType,needsSoak=netHits>0&&Boolean(origin.resistanceTest)&&Number(modifiedDamage??0)>0,iniMod=Number(raw.iniMod),hasIni=Number.isFinite(iniMod)&&iniMod!==0;return{outcome:needsSoak?'success':'failure',stageData:raw,derived:{netHits,baseDamage,modifiedDamage,damageType,finalDamage:needsSoak?undefined:netHits===0?0:Math.max(0,Number(modifiedDamage??baseDamage??0)),iniMod:hasIni?iniMod:undefined,iniCost:hasIni?Math.abs(iniMod):undefined,activeDefense:raw.activeDefense||undefined}}};
export const combatSoakReducer:StageReducer=({branch,roll,data})=>{const raw=(data??{})as any,systemFinal=Number(raw.modifiedDamage?.value),soakHits=roll.hits??0,finalDamage=Number.isFinite(systemFinal)?Math.max(0,systemFinal):Math.max(0,Number(branch.derived.modifiedDamage??branch.derived.baseDamage??0)-soakHits);return{outcome:finalDamage>0?'success':'failure',stageData:raw,derived:{soakHits,finalDamage}}};
export const suppressionDamageReducer:StageReducer=context=>combatDefenseReducer(context);
const combatInitialStage=(branch:Branch,origin?:RollRecord)=>branch.kind==='self'?'done':origin?.defenseTest&&(origin.hits??0)>0?'defense':'done';
const combatStages=(defenseTest:string,defenseReduce:string):StageSpec[]=>[{id:'defense',branch:'perTarget',testClasses:[defenseTest],trigger:'button',reduce:defenseReduce,defenseOptions:true,next:{onSuccess:'soak',onFailure:'done'},confirm:[{id:'ammoConfirmed',kind:'ammo',when:'derived.ammoPending'},{id:'initiativeApplied',kind:'initiative',when:'derived.iniCost'}]},{id:'soak',branch:'perTarget',testClasses:['PhysicalResistTest'],trigger:'button',reduce:'combatSoak',next:{always:'done'},confirm:[{id:'damageApplied',kind:'damage',when:'derived.finalDamage'}]}];
const isSuppression=(origin:{data?:any})=>Boolean(origin.data?.fireMode?.suppression);
export const combatAttack:FlowSpec={id:'combat-attack',match:origin=>COMBAT_ATTACK_TESTS.includes(origin.testClass)&&!isSuppression(origin),branches:'targets+self',initialStage:combatInitialStage,originExtract:['combatOrigin'],cardSections:['combatOrigin'],stages:combatStages('PhysicalDefenseTest','combatDefense')};
export const suppression:FlowSpec={id:'suppression',match:origin=>origin.testClass==='RangedAttackTest'&&isSuppression(origin),branches:'targets+self',initialStage:combatInitialStage,originExtract:['combatOrigin'],cardSections:['combatOrigin'],stages:combatStages('SuppressionDefenseTest','suppressionDamage')};
