import{confirmationAvailable,GLOBAL_CONFIRMATIONS}from'../core/flows/confirmation';import {flows}from'../core/flows/registry';import type{FlowSpec}from'../core/flows/spec';import{actionTypeLabel}from'../core/actions-catalog';import{HEAL_TRACKS,healingAmount}from'../core/flows/specs/general';import {DAMAGE_TRACKS,type Branch,type Modifier,type Transaction} from '../types';import{cardSections}from'./card-sections';
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const t=(key:string)=>game.i18n.localize(key);const eventLabel=(type:string)=>{const key=`SDF.Event.${type}`;return game.i18n.has?.(key)?t(key):type};const metric=(label:string,value:unknown)=>`<div class="test-value metric-row"><span class="value">${esc(label)}:</span><span class="value-result">${esc(value)}</span></div>`;
const button=(action:string,target:string,label:string,icon:string,data:Record<string,string>={},tier='sdf-btn--flow')=>`<button type="button" data-sdf-action="${action}" data-target-id="${esc(target)}" ${Object.entries(data).map(([key,value])=>`data-${key}="${esc(value)}"`).join(' ')} class="button ${tier}"><i class="fas ${icon}"></i> ${esc(label)}</button>`;
function modifierRow(m:Modifier){const sign=m.value>0?'+':'';const detail=[m.source,m.condition].filter(Boolean).join(' · ');return`<div class="sdf-modifier ${m.condition===t('SDF.Disabled')||m.condition===t('SDF.Masked')?'inactive':''}"><span><strong>${esc(m.label)}</strong>${detail?`<small>${esc(detail)}</small>`:''}</span><span class="sdf-mod-value">${sign}${m.value}</span></div>`}
const damageCode=(value:number,type?:string)=>{const key=`SDF.DamageCode.${type}`;return`${value}${type&&game.i18n.has?.(key)?esc(t(key)):''}`};
const damageLabel=(type?:string)=>{const key=`SDF.DamageType.${type}`;return type&&game.i18n.has?.(key)?t(key):type??''};
function targetSection(tx:Transaction,target:Branch,isGM:boolean){
    const attackHits=tx.origin.hits;
    const defense=target.rolls.defense;const resistance=target.rolls.soak;const damageApplied=target.confirmations.damageApplied?.payload as {value:number;type:string}|undefined;
    const netHits=Number(target.derived.netHits??0);const modifiedDamage=target.derived.modifiedDamage as number|undefined;const soakHits=target.derived.soakHits as number|undefined;const finalDamage=target.derived.finalDamage as number|undefined;const damageType=target.derived.damageType as string|undefined;
    const hit=netHits>0;
    const rows:string[]=[];
    if(defense){
        rows.push(metric(t('SDF.AttackHits'),attackHits??'—'));
        rows.push(metric(t('SDF.DefenseHits'),defense.hits??'—'));
        rows.push(metric(t('SDF.NetHits'),netHits));
    }
    const verdict=defense?`<div class="sdf-verdict sdf-verdict--${hit?'impact':'deflected'}"><i class="fas ${hit?'fa-burst':'fa-shield'}"></i> ${esc(hit?t('SDF.Hit'):t('SDF.Miss'))}</div>`:'';
    if(defense&&hit&&modifiedDamage!==undefined)rows.push(metric(t('SDF.Damage'),`${damageCode(modifiedDamage,damageType)}${damageType?` · ${esc(damageLabel(damageType))}`:''}`));
    if(resistance)rows.push(metric(t('SDF.SoakHits'),soakHits??0));
    const showFinal=target.stageId==='done'&&defense&&hit&&finalDamage!==undefined;
    if(showFinal)rows.push(metric(t('SDF.FinalDamage'),(finalDamage??0)>0?damageCode(finalDamage!,damageType):t('SDF.NoDamage')));
    const applied=damageApplied?`<div class="sdf-applied"><i class="fas fa-check"></i> ${esc(game.i18n.format('SDF.DamageApplied',{damage:damageCode(damageApplied.value,damageApplied.type)}))}</div>`:'';
    const canApply=target.stageId==='done'&&!damageApplied&&(finalDamage??0)>0&&DAMAGE_TRACKS.includes(damageType??'');
    const actions=[
        target.stageId==='defense'?button('defend',target.id,t('SDF.Defend'),'fa-shield-halved'):'',
        target.stageId==='soak'?button('resist',target.id,t('SDF.Resist'),'fa-heart-pulse'):'',
        canApply?`<div class="sdf-commit-zone">${button('apply-damage',target.id,game.i18n.format('SDF.ApplyDamage',{damage:damageCode(finalDamage!,damageType)}),'fa-user-injured',{},'sdf-btn--commit')}</div>`:'',
        isGM?button('correct',target.id,t('SDF.Correct'),'fa-wrench',{},'sdf-btn--gm'):''
    ].join('');
    const legacyStage=target.stageId==='defense'?'created':target.stageId==='soak'?'defended':'complete';
    return`<section class="sdf-target" data-stage="${target.stageId}"><header><span><i class="fas fa-crosshairs"></i> ${esc(target.name)}</span><span class="sdf-stage">${esc(t(`SDF.Stage.${legacyStage}`))}</span></header><div class="sdf-target-metrics">${rows.join('')}</div>${verdict}${applied}<div class="sdf-actions">${actions}</div></section>`
}
const label=(prefix:string,id:string)=>{const key=`SDF.${prefix}.${id}`;return game.i18n.has?.(key)?t(key):id.replace(/[-_]/g,' ').replace(/^./,value=>value.toUpperCase())};
const DEFENSE_MODES:[string,string,string][]=[['','SDF.Defense.Normal','fa-shield-halved'],['full_defense','SDF.Defense.FullDefense','fa-shield-heart']];const MELEE_DEFENSE_MODES:[string,string,string][]=[['dodge','SDF.Defense.Dodge','fa-person-running'],['block','SDF.Defense.Block','fa-hand-fist'],['parry','SDF.Defense.Parry','fa-hand-back-fist']];
const DEFENSE_MODE_LABELS:Record<string,string>={full_defense:'SDF.Defense.FullDefense',dodge:'SDF.Defense.Dodge',block:'SDF.Defense.Block',parry:'SDF.Defense.Parry'};
const defenseModeLabel=(mode:string)=>DEFENSE_MODE_LABELS[mode]?t(DEFENSE_MODE_LABELS[mode]):mode;
const HIDDEN_DERIVED=new Set(['iniMod','iniCost','activeDefense','drainType','fadeType','pendingEffects','selfPendingEffects']);
function effectsLine(branch:Branch){const applied=(branch.confirmations.effectsApplied??branch.confirmations.selfEffectsApplied)?.payload as any,info=branch.stageData.effects as any,originItem=(branch.stageData.origin as any)?.item,pendingCount=Number(branch.derived[branch.kind==='self'?'selfPendingEffects':'pendingEffects']??0);if(!applied&&pendingCount<=0)return'';const names:string[]=applied?.names??(info?.effects??[]).map((effect:any)=>effect?.name).filter(Boolean);const fallback=((branch.kind==='self'?originItem?.selfEffects:originItem?.targetedEffects)??[]).map((effect:any)=>effect?.name).filter(Boolean);const list=(names.length?names:fallback).join(', ');if(applied)return`<div class="sdf-applied"><i class="fas fa-wand-magic-sparkles"></i> ${esc(game.i18n.format('SDF.Effects.Applied',{effects:list||applied.count}))}</div>`;return`<div class="sdf-pending-effects"><i class="fas fa-wand-magic-sparkles"></i> ${esc(game.i18n.format('SDF.Effects.Pending',{effects:list||pendingCount}))}${info?.oversized||info?.unresolved?` <small>${esc(t('SDF.Effects.Unresolved'))}</small>`:''}</div>`}
function defenseControls(branch:Branch,melee:boolean){const cover=`<label class="sdf-cover-label">${esc(t('SDF.Defense.Cover'))} <select class="sdf-cover" data-sdf-cover>${[[0,'SDF.Defense.CoverNone'],[2,'SDF.Defense.CoverPartial'],[4,'SDF.Defense.CoverGood']].map(([value,key])=>`<option value="${value}">${esc(t(key as string))}</option>`).join('')}</select></label>`;const modes=[...DEFENSE_MODES,...(melee?MELEE_DEFENSE_MODES:[])].map(([mode,key,icon])=>button('defend',branch.id,t(key),icon,{'active-defense':mode})).join('');return`<div class="sdf-defense-options">${cover}${modes}</div>`}
// The First Aid test does not tell us which track was treated, so the healer picks it explicitly.
const healTrackControl=()=>`<label class="sdf-heal-label">${esc(t('SDF.Heal.Track'))} <select class="sdf-heal-track" data-sdf-heal-track><option value="">${esc(t('SDF.Heal.TrackNone'))}</option>${HEAL_TRACKS.map(track=>`<option value="${track}">${esc(damageLabel(track))}</option>`).join('')}</select></label>`;
function rail(spec:FlowSpec,branch:Branch){const stages=spec.stages.filter(value=>value.branch===(branch.kind==='target'?'perTarget':'self'));if(!stages.length)return'';const pending=stages.find(value=>(value.confirm??[]).some(confirm=>confirmationAvailable(confirm,branch)));const active=pending?.id??branch.stageId,ids=[...stages.map(value=>value.id),'done'],index=Math.max(0,ids.indexOf(active));return`<ol class="sdf-rail" aria-label="${esc(t('SDF.Rail.Label'))}">${ids.map((id,i)=>{const stage=stages.find(value=>value.id===id),confirmed=Boolean(stage?.confirm?.length)&&stage!.confirm!.every(confirm=>Boolean(branch.confirmations[confirm.id])),rolled=Boolean(branch.rolls[id]),state=i<index?(rolled||confirmed?'done':'skipped'):i===index?'current':i===index+1?'next':'pending';return`<li data-rail-stage="${esc(id)}" data-state="${state}"${state==='current'?' aria-current="step"':''}><span>${esc(id==='done'?t('SDF.Step.done'):t(`SDF.Step.${id}`))}</span></li>`}).join('')}</ol>`}
function genericBranchSection(spec:FlowSpec,branch:Branch,isGM:boolean,origin:Transaction['origin'],originKind?:string){const stage=spec.stages.find(value=>value.id===branch.stageId),rolls=Object.entries(branch.rolls).map(([id,roll])=>metric(label('Stage',id),roll.hits??'—')).join(''),activeDefense=branch.derived.activeDefense as string|undefined,defenseRow=activeDefense?metric(t('SDF.Derived.activeDefense'),`${defenseModeLabel(activeDefense)}${branch.derived.iniCost?` (−${branch.derived.iniCost})`:''}`):'',healRow=spec.id==='heal'?metric(t('SDF.Heal.Amount'),healingAmount(origin)): '',derived=defenseRow+healRow+Object.entries(branch.derived).filter(([id,value])=>value!==undefined&&!HIDDEN_DERIVED.has(id)).map(([id,value])=>metric(label('Derived',id),value)).join('');const confirmations=[...spec.stages.flatMap(value=>value.confirm??[]),...GLOBAL_CONFIRMATIONS].filter(value=>confirmationAvailable(value,branch));const defenseStage=Boolean(stage?.defenseOptions&&stage.trigger==='button'),stageButton=stage?.trigger==='button'&&!(stage.gm&&!isGM)?button(stage.action??'run-stage',branch.id,label('Action',stage.id),stage.action==='conjure-opposed'?'fa-hat-wizard':stage.action==='conjure-drain'?'fa-brain':'fa-dice',{'stage-id':stage.id}):'';const commitActions=confirmations.map(value=>{const lbl=value.kind==='initiative'?game.i18n.format('SDF.Confirm.initiativeApplied',{value:Number(branch.derived.iniCost??0)}):label('Confirm',value.id);return button('confirm',branch.id,lbl,value.kind==='initiative'?'fa-bolt':'fa-check',{'confirm-id':value.id,'confirm-kind':value.kind},'sdf-btn--commit')}).join('');const actions=[defenseStage?defenseControls(branch,originKind==='MeleeAttackTest'):stageButton,confirmations.some(value=>value.kind==='heal')?healTrackControl():'',commitActions?`<div class="sdf-commit-zone">${commitActions}</div>`:'',isGM?button('correct',branch.id,t('SDF.Correct'),'fa-wrench',{},'sdf-btn--gm'):'' ].join('');const stageLabel=branch.stageId==='done'?t('SDF.Stage.complete'):label('Stage',branch.stageId),netHits=Number(branch.derived.netHits??0),combatVerdict=(spec.id==='combat-attack'||spec.id==='suppression')&&branch.rolls.defense?`<div class="sdf-verdict sdf-verdict--${netHits>0?'impact':'deflected'}"><i class="fas ${netHits>0?'fa-burst':'fa-shield'}"></i> ${esc(netHits>0?t('SDF.Hit'):t('SDF.Miss'))}</div>`:'';return`<section class="sdf-target sdf-branch sdf-branch-${branch.kind}" data-stage="${esc(branch.stageId)}"><header><span><i class="fas ${branch.kind==='self'?'fa-user':'fa-crosshairs'}"></i> ${esc(branch.name)}</span><span class="sdf-stage">${esc(stageLabel)}</span></header>${rail(spec,branch)}<div class="sdf-target-metrics">${rolls}${derived}</div>${combatVerdict}${effectsLine(branch)}<div class="sdf-actions">${actions}</div></section>`}
function flowSpec(tx:Transaction){try{return flows.get(tx.flowId)}catch{return undefined}}
function customSections(tx:Transaction,spec?:FlowSpec){if(!spec)return'';return(spec.cardSections??[]).map(id=>cardSections.has(id)?`<section class="sdf-card-section sdf-card-section-${esc(id)}">${cardSections.get(id)({transaction:tx,spec,escape:esc,localize:t})}</section>`:'').join('')}
export function renderCard(
tx:Transaction,{isGM=false,canAuthor=false}={}){const r=tx.origin,spec=flowSpec(tx),generic=Boolean(spec),combatFlow=tx.flowId==='combat-attack'||tx.flowId==='suppression',announced=Boolean(tx.calledShotAnnounced),economyLabel=actionTypeLabel(tx.economy?.actionType),hasDetails=r.pool!==undefined,simpleFlow=Object.values(tx.branches).every(branch=>branch.kind!=='target'),edgeLine=r.edge?.pushTheLimit||r.edge?.secondChance?`<div class="sdf-edge"><i class="fas fa-certificate"></i> ${esc(t('SDF.Edge.Used'))}: ${esc([r.edge.pushTheLimit?t('SDF.Edge.PushTheLimit'):'',r.edge.secondChance?t('SDF.Edge.SecondChance'):''].filter(Boolean).join(', '))}</div>`:'',verdictLine=r.threshold!==undefined&&r.hits!==undefined&&simpleFlow&&hasDetails?`<div class="sdf-verdict sdf-verdict--${r.hits>=r.threshold?'success':'failure'}"><i class="fas ${r.hits>=r.threshold?'fa-check':'fa-xmark'}"></i> ${esc(r.hits>=r.threshold?t('SDF.Succeeded'):t('SDF.Failed'))}</div>`:'',title=r.title||r.kind,entities=[r.actorName,r.itemName].filter(Boolean).map(name=>`<div class="document"><h3 class="header-name">${esc(name)}</h3></div>`).join(''),modifiers=r.modifiers.map(modifierRow).join(''),targets=Object.values(tx.branches).map(branch=>generic?genericBranchSection(spec!,branch,isGM,r,r.kind):targetSection(tx,branch,isGM)).join('');return`<article class="sr5 chat-card roll-card sr5-roll-card-v2 sr5-dice-flow" data-flow-id="${esc(tx.flowId)}" data-transaction-id="${tx.id}" data-revision="${tx.revision}"><div class="card-title card-header card-header--title"><span class="test-name">${esc(title)}</span><span class="sdf-revision">${game.i18n.format('SDF.Revision',{revision:tx.revision})}</span></div>${entities?`<div class="card-title card-header card-header--entities"><div class="container container--fluid">${entities}</div></div>`:''}<div class="card-main-content">${hasDetails?`<div class="card-content card-content--code"><div class="test-line"><span class="test-code">${esc(r.basePool??r.pool)}${r.modifiers.length?` ${r.modifiers.map(m=>`${m.value>=0?'+ ':''}${m.value}`).join(' ')}`:''}${r.limit!==undefined?` [${r.limit}]`:''}${r.threshold!==undefined?` (${r.threshold})`:''}</span></div></div><div class="card-content card-content--metrics"><div class="left-side">${r.limit!==undefined?metric(t('SDF.Limit'),r.limit):''}${r.threshold!==undefined?metric(t('SDF.Threshold'),r.threshold):''}${r.rawHits!==undefined&&r.rawHits!==r.hits?metric(t('SDF.RawHits'),r.rawHits):''}</div><div class="right-side">${metric(t('SDF.DicePool'),r.pool)}${metric(t('SDF.Hits'),r.hits??'—')}${r.glitches?metric(t('SDF.Glitches'),r.glitches):''}</div></div>${modifiers?`<details class="sdf-modifiers"><summary><i class="fas fa-sliders"></i> ${esc(t('SDF.Modifiers'))}</summary><div>${modifiers}</div></details>`:''}`:`<div class="card-content sdf-private"><i class="fas fa-user-secret"></i> ${esc(t('SDF.PrivateRoll'))}</div>`}${edgeLine}${verdictLine}${economyLabel?`<div class="sdf-action-type"><i class="fas fa-hourglass-half"></i> ${esc(game.i18n.format('SDF.Economy.ActionLabel',{type:t(economyLabel)}))}</div>`:''}${customSections(tx,spec)}${announced?`<div class="sdf-called-shot-badge"><i class="fas fa-crosshairs"></i> ${esc(t('SDF.CalledShot.Announced'))}</div>`:''}<div class="sdf-targets">${targets||`<p class="sdf-empty">${esc(t('SDF.NoTargets'))}</p>`}</div>${canAuthor||isGM?`<div class="sdf-card-actions">${button('add-target','',t('SDF.AddTarget'),'fa-crosshairs')}${combatFlow?button('announce-called-shot','',t(announced?'SDF.CalledShot.Retract':'SDF.CalledShot.Announce'),'fa-crosshairs'):''}</div>`:''}<details class="sdf-history"><summary><i class="fas fa-clock-rotate-left"></i> ${esc(t('SDF.History'))}</summary><ol>${tx.events.map(e=>`<li class="${e.invalidated?'invalid':''}">${new Date(e.at).toLocaleTimeString()} — ${esc(eventLabel(e.type))}</li>`).join('')}</ol></details></div></article>`}
