import{extractors}from'../core/flows/registry';import{cardSections}from'./card-sections';import{combatOriginExtractor}from'./extract';
const value=(input:unknown)=>Number.isFinite(Number(input))?Number(input):'—';
export function registerCombatPresentation(){if(!extractors.has('combatOrigin'))extractors.register('combatOrigin',combatOriginExtractor);if(!cardSections.has('combatOrigin'))cardSections.register('combatOrigin',({transaction,spec,escape,localize})=>{const branches=Object.values(transaction.branches),combat=(branches[0]?.stageData.origin as any)?.combat;if(!combat)return'';const row=(label:string,result:unknown)=>`<div class="metric-row"><span class="value">${escape(localize(label))}:</span><span class="value-result">${escape(result)}</span></div>`,parts:string[]=[];const targetCount=branches.filter(branch=>branch.kind==='target').length;if(spec.id==='combat-attack'&&targetCount>1){const pool=Number((transaction.origin as any).pool),perTarget=Number.isFinite(pool)&&pool>0?Math.floor(pool/targetCount):undefined,split=game.i18n.format('SDF.Combat.PoolSplitHint',{count:targetCount})+(perTarget!==undefined?` ${game.i18n.format('SDF.Combat.PoolSplitSuggest',{pool,perTarget})}`:'');parts.push(`<div class="sdf-combat-advisory"><strong><i class="fas fa-triangle-exclamation"></i> ${escape(localize('SDF.Combat.MultiAttack'))}</strong><p>${escape(split)}</p><p>${escape(localize('SDF.Combat.RecoilHint'))}</p></div>`)}if(combat.fireMode){const mode=game.i18n.has?.(combat.fireMode.label)?localize(combat.fireMode.label):combat.fireMode.label;parts.push(`<div class="sdf-combat-group"><strong>${escape(localize('SDF.Combat.FireMode'))}</strong>${row('SDF.Combat.Mode',mode)}${row('SDF.Combat.Rounds',combat.fireMode.rounds)}${row('SDF.Combat.DefenseModifier',combat.fireMode.defense)}</div>`)}if(combat.ammo){const confirmed=branches.find(branch=>branch.kind==='self')?.confirmations.ammoConfirmed?.payload as any,after=confirmed?.after??(combat.ammo.deferred?combat.ammo.plannedAfter:combat.ammo.after),status=confirmed?'SDF.Combat.AmmoConfirmed':combat.ammo.deferred?'SDF.Combat.AmmoPending':combat.ammo.fallback?'SDF.Combat.AmmoFallback':'SDF.Combat.AmmoImmediate';parts.push(`<div class="sdf-combat-group"><strong>${escape(localize('SDF.Combat.Ammo'))}</strong>${row('SDF.Combat.BeforeAfter',`${value(confirmed?.before??combat.ammo.before)} → ${value(after)} / ${value(combat.ammo.max)}`)}${row('SDF.Status',localize(status))}</div>`)}if(combat.recoil)parts.push(`<div class="sdf-combat-group"><strong>${escape(localize('SDF.Combat.Recoil'))}</strong>${row('SDF.Combat.BeforeAfter',`${value(combat.recoil.before)} → ${value(combat.recoil.after)}`)}${row('SDF.Combat.Compensation',value(combat.recoil.compensation))}</div>`);if(combat.reach!==undefined)parts.push(`<div class="sdf-combat-group"><strong>${escape(localize('SDF.Combat.Melee'))}</strong>${row('SDF.Combat.Reach',combat.reach)}</div>`);if(Number(combat.blast?.radius)>0)parts.push(`<div class="sdf-combat-group"><strong><i class="fas fa-explosion"></i> ${escape(localize('SDF.Combat.Blast'))}</strong>${row('SDF.Combat.BlastRadius',`${Number(combat.blast.radius)} m`)}${combat.blast.dropoff?row('SDF.Combat.BlastDropoff',`${Number(combat.blast.dropoff)}/m`):''}</div>`);if(combat.calledShot){const type=combat.calledShot.label&&game.i18n.has?.(combat.calledShot.label)?localize(combat.calledShot.label):localize('SDF.CalledShot.Generic');parts.push(`<div class="sdf-combat-group sdf-called-shot-group"><strong><i class="fas fa-crosshairs"></i> ${escape(localize('SDF.CalledShot.Label'))}</strong>${row('SDF.CalledShot.Type',`${type} (-${combat.calledShot.mod})`)}</div>`)}if(combat.targetRanges?.length){const ranges=combat.targetRanges.map((range:any)=>{const branch=branches.find(value=>value.tokenUuid===range.tokenUuid),label=game.i18n.has?.(range.label)?localize(range.label):range.label??'';return row('SDF.Combat.RangeTarget',`${branch?.name??range.tokenUuid??'?'} · ${range.distance} m · ${label} (${range.modifier})`)}).join('');parts.push(`<div class="sdf-combat-group"><strong>${escape(localize('SDF.Combat.Range'))}</strong>${ranges}</div>`)}for(const[group,changes]of Object.entries(combat.poolGroups??{})){if(!(changes as any[]).length)continue;parts.push(`<details class="sdf-combat-group"><summary>${escape(localize(`SDF.Combat.Group.${group}`))}</summary>${(changes as any[]).map(change=>row(String(change.name),`${change.value>=0?'+':''}${change.value}`)).join('')}</details>`)}return`<div class="sdf-combat-origin">${parts.join('')}</div>`})}
