import{MODULE_ID}from'../types';
export interface DeferredAmmoState {deferred:boolean;itemUuid?:string;rounds:number;before?:number;plannedAfter?:number;fallback?:boolean}
const states=new WeakMap<object,DeferredAmmoState>();const finite=(value:unknown)=>Number.isFinite(Number(value))?Number(value):undefined;
export const ammoState=(test:any)=>test&&typeof test==='object'?states.get(test):undefined;
export async function deferAmmoConsumption(test:any){const item=test?.item,fireMode=test?.data?.fireMode;if(!item?.isRangedWeapon?.()||!fireMode||Number(fireMode.value)<=0)return false;const rounds=Math.max(0,Number(fireMode.value)||0),before=finite(item.system?.ammo?.current?.value);if(!item.hasAmmo?.(rounds))ui.notifications?.warn('SR5.MissingRessource.SomeAmmo',{localize:true});await test.actor?.addProgressiveRecoil?.(fireMode);states.set(test,{deferred:true,itemUuid:item.uuid,rounds,before,plannedAfter:before===undefined?undefined:Math.max(0,before-rounds)});return true}
export function noteImmediateAmmo(test:any){const rounds=Math.max(0,Number(test?.data?.fireMode?.value)||0),before=finite(test?.item?.system?.ammo?.current?.value);if(test&&typeof test==='object')states.set(test,{deferred:false,itemUuid:test.item?.uuid,rounds,before})}
export function noteAmmoFallback(test:any){if(test&&typeof test==='object')states.set(test,{deferred:false,itemUuid:test.item?.uuid,rounds:Math.max(0,Number(test?.data?.fireMode?.value)||0),fallback:true})}
export function installAmmoWrapper(){if(!globalThis.window?.libWrapper||!game.shadowrun5e?.tests?.RangedAttackTest)return;try{window.libWrapper.register(MODULE_ID,'game.shadowrun5e.tests.RangedAttackTest.prototype.consumeWeaponAmmo',async function(this:any,wrapped:(...args:any[])=>Promise<boolean>,...args:any[]){if(!game.settings.get(MODULE_ID,'deferAmmo')){noteImmediateAmmo(this);return wrapped(...args)}try{if(await deferAmmoConsumption(this))return true;return wrapped(...args)}catch(error){noteAmmoFallback(this);console.warn(`${MODULE_ID} | Deferred ammunition unavailable; using system consumption`,error);return wrapped(...args)}},'MIXED')}catch(error){console.warn(`${MODULE_ID} | Cannot wrap ammunition consumption; display only`,error)}}
