import{CALLED_SHOTS,CALLED_SHOT_MODIFIER,calledShotByKey,type CalledShot}from'../core/calledshots';import{COMBAT_ATTACK_TESTS}from'../core/flows/specs/combat';
const ADD_MODE=2,CHANGE_PRIORITY=20;
function setCalledShotModifier(test:any,shot?:CalledShot){const pool=test?.data?.pool;if(!pool)return;pool.changes=pool.changes??[];const index=pool.changes.findIndex((change:any)=>change.name===CALLED_SHOT_MODIFIER);if(shot){const change={name:CALLED_SHOT_MODIFIER,mode:ADD_MODE,value:-Math.abs(shot.mod),priority:CHANGE_PRIORITY,source:'',enabled:true};if(index>=0)pool.changes[index]=change;else pool.changes.push(change)}else if(index>=0)pool.changes.splice(index,1);try{test.prepareBaseValues?.();test.calculateBaseValues?.();test.validateBaseValues?.()}catch(error){console.warn('sr5-dice-flow | Called-shot pool recompute failed',error)}}
function injectCalledShot(app:any,element:HTMLElement){const test=app?.test;if(!element||!COMBAT_ATTACK_TESTS.includes(test?.data?.type))return;const form=element.querySelector('form')??element.querySelector('.window-content');if(!form||form.querySelector('.sdf-called-shot'))return;const current=test.data?.calledShot?.key??'',options=[`<option value="">${game.i18n.localize('SDF.CalledShot.None')}</option>`,...CALLED_SHOTS.map(shot=>`<option value="${shot.key}"${shot.key===current?' selected':''}>${game.i18n.localize(shot.label)} (-${shot.mod})</option>`)].join(''),wrapper=document.createElement('div');wrapper.className='sdf-called-shot form-group';wrapper.innerHTML=`<label><i class="fas fa-crosshairs"></i> ${game.i18n.localize('SDF.CalledShot.Label')}</label><select class="sdf-called-shot-select">${options}</select>`;form.prepend(wrapper);wrapper.querySelector('select')!.addEventListener('change',event=>{const shot=calledShotByKey((event.target as HTMLSelectElement).value);test.data.calledShot=shot?{key:shot.key,label:shot.label,mod:shot.mod}:undefined;setCalledShotModifier(test,shot);void app.render()})}
export function installCalledShotInjection(){Hooks.on('renderTestDialog',(app:any,element:any)=>{try{injectCalledShot(app,element instanceof HTMLElement?element:element?.[0]??app?.element)}catch(error){console.warn('sr5-dice-flow | Called-shot injection failed',error)}})}
