import{extractors}from'../core/flows/registry';import type{FlowOrigin}from'../core/flows/spec';import{cardSections}from'./card-sections';
export function spellOriginExtractor(origin:FlowOrigin){const data=origin.data??{},sys=origin.test?.item?.system;if(!sys)return{spell:undefined};const drainDamage=data.drainDamage?{value:Number(data.drainDamage.value??data.drainDamage.base)||0,type:data.drainDamage.type?.value}:undefined;return{spell:{category:sys.category,type:sys.type,combatType:sys.combat?.type,force:Number(data.force)||undefined,drain:Number(data.drain)||undefined,drainDamage}}}
export function registerMagicPresentation(){if(!extractors.has('spellOrigin'))extractors.register('spellOrigin',spellOriginExtractor);if(!cardSections.has('spellOrigin'))cardSections.register('spellOrigin',({transaction,escape,localize})=>{const spell=(Object.values(transaction.branches)[0]?.stageData.origin as any)?.spell;if(!spell)return'';const row=(label:string,result:unknown)=>`<div class="metric-row"><span class="value">${escape(localize(label))}:</span><span class="value-result">${escape(result)}</span></div>`,parts:string[]=[];const category=spell.category&&game.i18n.has?.(`SR5.SpellCategory.${spell.category}`)?localize(`SR5.SpellCategory.${spell.category}`):spell.category;if(category)parts.push(row('SDF.Magic.Category',`${category}${spell.combatType?` (${escape(localize(`SDF.Magic.CombatType.${spell.combatType}`))})`:''}`));if(spell.force!==undefined)parts.push(row('SDF.Magic.Force',spell.force));if(spell.drain!==undefined)parts.push(row('SDF.Magic.DrainValue',spell.drain));if(!parts.length)return'';return`<div class="sdf-combat-origin sdf-magic-origin"><div class="sdf-combat-group"><strong><i class="fas fa-wand-magic-sparkles"></i> ${escape(localize('SDF.Magic.Spell'))}</strong>${parts.join('')}</div></div>`})}
